import{_ as a,o as i,c as e,a2 as n}from"./chunks/framework.7w-lhQN6.js";const k=JSON.parse('{"title":"VS Code 확장","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/vscode-extension.md","filePath":"ko/guide/vscode-extension.md","lastUpdated":1793550481000}'),t={name:"ko/guide/vscode-extension.md"};function l(o,s,h,d,p,r){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="vs-code-확장" tabindex="-1">VS Code 확장 <a class="header-anchor" href="#vs-code-확장" aria-label="Permalink to &quot;VS Code 확장&quot;">​</a></h1><p>이 문서를 끝내면 확장이 설치되고 온보딩을 마친 상태가 되며, activity bar의 MCP Lens 아이콘에서 자기 자신의 비용 × 사용량 매트릭스를 직접 보게 된다. 이 확장이 MCP Lens의 주된 배포 경로다. 스캔, 훅 설치, 리포트, 의존성 분석이 모두 확장 안에서 이뤄지므로 별도의 CLI 설치가 필요 없다.</p><h2 id="요구-사항" tabindex="-1">요구 사항 <a class="header-anchor" href="#요구-사항" aria-label="Permalink to &quot;요구 사항&quot;">​</a></h2><ul><li>Node.js 20 이상.</li><li>VS Code 1.90 이상.</li></ul><h2 id="설치" tabindex="-1">설치 <a class="header-anchor" href="#설치" aria-label="Permalink to &quot;설치&quot;">​</a></h2><p>확장은 아직 VS Code Marketplace에 게시되지 않았다. <code>.vsix</code>를 직접 빌드해서 로컬에 설치한다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/seodduu/MCPLens.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MCPLens</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp-context-lens</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # creates packages/extension/*.vsix</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-extension</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/extension/mcp-context-lens-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.vsix</span></span></code></pre></div><p><code>&lt;version&gt;</code>은 <code>npm run package</code>가 <code>.vsix</code> 파일 이름에 찍어 준 버전으로 바꿔 넣는다. <code>code --install-extension</code>은 확장이 설치되었음을 확인하는 줄을 출력한다.</p><h2 id="온보딩-walkthrough-실행" tabindex="-1">온보딩 walkthrough 실행 <a class="header-anchor" href="#온보딩-walkthrough-실행" aria-label="Permalink to &quot;온보딩 walkthrough 실행&quot;">​</a></h2><p>VS Code를 다시 연다. activity bar에 MCP Lens 아이콘이 나타나고, 온보딩 walkthrough가 자동으로 열린다. 단계는 순서대로 4개다.</p><ol><li><strong>Scan</strong>: 클라이언트에 설정된 MCP 서버를 스캔해서 각 툴 정의가 소모하는 토큰 수를 잰다.</li><li><strong>Install hooks</strong>: 사용하는 클라이언트에 훅을 설치한다. 그러면 리포트의 0이 실제 호출 수로 채워지기 시작한다.</li><li><strong>Dependency analysis</strong>: 실제로 연결된 서버를 기준으로 어떤 툴을 필터링하거나 제거해도 안전한지 LLM에게 판단시킨다 (이 단계가 실행되기 전에 아래의 동의 선택을 먼저 본다).</li><li><strong>Enable global actions</strong>: 명시적으로 허용하면 확장이 클라이언트 설정 파일을 편집해 툴을 끌 수 있게 된다.</li></ol><p>온보딩이 끝나면 activity bar 아이콘 아래에 <code>Cost × Usage Matrix</code>와 <code>Setup Status</code> 두 뷰가 생긴다.</p><h2 id="자동-실행-범위-정하기" tabindex="-1">자동 실행 범위 정하기 <a class="header-anchor" href="#자동-실행-범위-정하기" aria-label="Permalink to &quot;자동 실행 범위 정하기&quot;">​</a></h2><p>마지막 온보딩 단계는 질문 하나를 던진다. 새로 연결된 MCP 서버를 앞으로 확장이 알아서 처리할지 묻는 것이다. 선택지는 세 가지다.</p><ul><li>스캔과 의존성 분석을 모두 맡긴다.</li><li>스캔만 맡기고 분석은 직접 실행한다 (분석은 LLM 토큰을 쓰므로, 의도적으로 트리거하고 싶은 사람도 있다).</li><li>둘 다 직접 한다.</li></ul><p>이 질문에 답하기 전에는 아무것도 자동으로 실행되지 않는다. 자동 처리를 켜면 이후 새로 연결하는 서버만 자동으로 처리되며, 이미 기록된 동의를 재사용할 뿐 다시 묻지 않는다. 동의는 <code>MCP Lens: Withdraw Inference Consent</code> 커맨드로 언제든 철회할 수 있고, 이 커맨드는 자동 분석도 함께 멈춘다. 자동 스캔과 자동 분석은 <code>mcpLens.autoScan</code>, <code>mcpLens.autoAnalyze</code> 설정으로 각각 따로 끌 수 있다.</p><h2 id="로컬에-남는-것" tabindex="-1">로컬에 남는 것 <a class="header-anchor" href="#로컬에-남는-것" aria-label="Permalink to &quot;로컬에 남는 것&quot;">​</a></h2><p>모든 데이터는 자기 기기의 <code>~/.mcplens/lens.db</code> (SQLite)에 저장된다. MCP Lens는 세션·턴·호출 ID, 클라이언트 이름, 서버·툴 이름, 관찰 시각, 호출 소요 시간, 호출 에러 여부, 그리고 스캔한 툴 정의의 토큰 수를 수집한다. 대화 본문, 프롬프트, 툴 입력, 툴 응답, 어시스턴트 응답 본문, 소스 코드는 절대 수집하지 않는다. 기기 밖으로 나가는 기능은 의존성 분석 하나뿐이며, 이 기능은 walkthrough 3단계에서 고른 LLM 제공자에게 툴 정의와 집계된 사용량 수치만 보낸다.</p><p>원본 클라이언트 로그는 항상 읽기 전용이다. MCP Lens는 이를 절대 수정하거나 옮기지 않는다.</p><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p><code>calls</code> 열을 0에서 실제 수치로 바꾸려면 <a href="/MCPLens/ko/guide/claude-code">Claude Code</a>, <a href="/MCPLens/ko/guide/codex">Codex</a>, <a href="/MCPLens/ko/guide/gemini-cli">Gemini CLI</a>에 훅을 설치하거나, 확장 안에서 <code>MCP Lens: Install Hooks for All Clients</code> 커맨드로 한 번에 전부 설치한다. 매트릭스의 모든 열과 권장 조치를 이해하려면 <a href="/MCPLens/ko/guide/reading-reports">리포트 읽기</a>를 본다. 스캔이 내부에서 어떻게 동작하는지는 <a href="/MCPLens/ko/concepts/how-it-works">동작 원리</a>를 본다.</p>`,21)])])}const g=a(t,[["render",l]]);export{k as __pageData,g as default};
